package main

import (
	"bufio"
	"fmt"
	"os"
)

type Point struct {
	x, y int
}

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	var s string
	fmt.Fscan(in, &n, &s)

	count := make(map[Point]int)
	pos := Point{0, 0}
	count[pos] = 1

	var answer int64

	for _, command := range s {
		switch command {
		case 'U':
			pos.y++
		case 'R':
			pos.x++
		case 'D':
			pos.y--
		case 'L':
			pos.x--
		}

		answer += int64(count[pos])
		count[pos]++
	}

	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()
	fmt.Fprintln(out, answer)
}

